param(
    [string]$ToolRoot = "",
    [string]$DecompSupportRoot = "",
    [string]$CodeBin = "E:\ppssppvr\oot3d_decomp\work\extract\exefs\code.bin",
    [string]$WorkRoot = "I:\oot3dre_work",
    [string]$Output = "",
    [switch]$Verify
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
if ([string]::IsNullOrWhiteSpace($ToolRoot)) {
    $ToolRoot = Join-Path $repoRoot "tools\oot3d\oot3d_asset_tool"
}
if ([string]::IsNullOrWhiteSpace($DecompSupportRoot)) {
    $DecompSupportRoot = Join-Path $repoRoot "tools\oot3d\decomp_support"
}
if ([string]::IsNullOrWhiteSpace($Output)) {
    $Output = Join-Path $WorkRoot "asset_replacement_ledger\oot3d_asset_replacement_readiness_ledger.json"
}

function Require-Path([string]$Path, [string]$Label) {
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "$Label not found: $Path"
    }
}

function Assert-Condition([bool]$Condition, [string]$Message) {
    if (-not $Condition) {
        throw "OOT3D asset replacement ledger failed: $Message"
    }
}

function Get-JsonValue([object]$Object, [string]$Name) {
    if ($null -eq $Object) {
        return $null
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) {
        return $null
    }
    return $property.Value
}

function Get-IntValue([object]$Value) {
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) {
        return 0
    }
    return [int]$Value
}

Require-Path $ToolRoot "Tool root"
Require-Path $DecompSupportRoot "OOT3D decomp support root"
Require-Path $CodeBin "Extracted OOT3D ExeFS code.bin"
Require-Path $WorkRoot "Generated work root"
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Output) | Out-Null

Push-Location $ToolRoot
try {
    $env:PYTHONPATH = Join-Path $ToolRoot "src"
    Write-Host "python -m oot3d_asset_tool audit-asset-replacement-ledger $WorkRoot --output $Output --decomp-support-root $DecompSupportRoot --code-bin $CodeBin"
    & python -m oot3d_asset_tool audit-asset-replacement-ledger `
        $WorkRoot `
        --output $Output `
        --decomp-support-root $DecompSupportRoot `
        --code-bin $CodeBin
    if ($LASTEXITCODE -ne 0) {
        throw "oot3d_asset_tool failed with exit code $LASTEXITCODE"
    }
}
finally {
    Pop-Location
}

Require-Path $Output "OOT3D asset replacement ledger"
