    Assert-Condition ([int]$code.metrics.direct_smooth_tail_codegen_probe_pure_c_rot_target_load_register_order_rows -eq 0) "expected no pure-C smooth-tail row to recover exact rot load register order yet"
    Assert-Condition ([int]$code.metrics.direct_smooth_tail_codegen_probe_no_saved_r6_and_rot_target_load_register_order_rows -eq 9) "expected 9 smooth-tail rows to combine no-r6 frame with exact rot register order"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_rows -eq 60) "expected 60 isolated state-gate codegen probe rows"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_compiled -eq 60) "expected all isolated state-gate codegen probes to compile"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_pure_c_rows -eq 50) "expected 50 pure-C isolated state-gate rows"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_pure_c_cmpne_chain_recovered_rows -eq 0) "expected no pure-C isolated state-gate row to recover cmpne"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_pure_c_range_check_avoided_rows -eq 20) "expected 20 pure-C isolated state-gate rows to avoid range-check lowering"
    Assert-Condition ([int]$code.metrics.direct_state_gate_codegen_probe_inline_asm_cmpne_chain_recovered_rows -eq 10) "expected inline asm isolated state-gate rows to recover cmpne"
    Assert-Condition ($code.metrics.direct_state_gate_codegen_probe_best_pure_c_branch_shape -eq "explicit-eq-chain") "expected best pure-C isolated state-gate shape to remain explicit eq chain"
    Assert-Condition ([int]$code.metrics.frontier_compiled_packet_seed_functions -eq 15) "expected 15 compiled-packet frontier seed functions"
    Assert-Condition ([int]$code.metrics.frontier_compile_blocked_seed_functions -eq 0) "expected no compile-blocked frontier seed functions"
    Assert-Condition ([int]$code.metrics.frontier_complete_split_spans -eq 13) "expected 13 complete direct split spans"
    Assert-Condition ([int]$code.metrics.direct_split_promotion_workorders -eq 17) "expected 17 direct split promotion workorders"
    Assert-Condition ([int]$code.metrics.direct_split_promotion_complete_spans -eq 13) "expected 13 complete direct split promotion spans"
    Assert-Condition ([int]$code.metrics.direct_split_promotion_truncated_spans -eq 4) "expected 4 truncated direct split promotion spans"
    Assert-Condition ([int]$code.metrics.direct_split_promotion_ready_spans -eq 0) "expected no direct split spans to be promotion-ready yet"
    Assert-Condition ([int]$code.metrics.frontier_open_sample_materialized_artifact_count -eq $code.metrics.frontier_open_function_samples.Count) "expected all current open frontier samples to have materialized C artifacts"
}

Write-Host "OOT3D asset replacement ledger: $Output"
Write-Host "records=$($ledger.record_count) statuses=$($ledger.status_counts | ConvertTo-Json -Compress)"
